CREATE OR REPLACE FUNCTION public.guard_side_letter_change_request() RETURNS trigger LANGUAGE plpgsql SET search_path TO public AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Side letter change requests cannot be deleted'; END IF; IF OLD.status<>'pending' THEN RAISE EXCEPTION 'Decided change requests are immutable'; END IF; IF NEW.status IN ('approved','declined') THEN IF NEW.decided_by IS NULL OR NEW.decided_at IS NULL THEN RAISE EXCEPTION 'Record the authorized decision maker'; END IF; IF NOT EXISTS(SELECT 1 FROM public.fund_managers WHERE offering_id=OLD.offering_id AND user_id=NEW.decided_by) AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=NEW.decided_by AND role::text IN ('admin','super_admin','operations','fund_administration','legal','compliance')) AND NOT public.is_live_fund_reviewer(NEW.decided_by,OLD.offering_id) THEN RAISE EXCEPTION 'Only authorized exact-fund reviewers may decide'; END IF; END IF; IF NEW.status='declined' AND coalesce(btrim(NEW.decision_reason),'')='' THEN RAISE EXCEPTION 'A decline reason is required'; END IF; IF NEW.after_snapshot IS DISTINCT FROM OLD.after_snapshot OR NEW.proposed_by IS DISTINCT FROM OLD.proposed_by THEN RAISE EXCEPTION 'Proposal content cannot be changed'; END IF; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.decide_routine_side_letter(_request uuid,_actor uuid,_decision text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.side_letter_change_requests%ROWTYPE; l public.side_letters%ROWTYPE; s jsonb; v integer; BEGIN SELECT * INTO r FROM public.side_letter_change_requests WHERE id=_request FOR UPDATE; IF NOT FOUND OR r.status<>'pending' THEN RAISE EXCEPTION 'Proposal is no longer pending'; END IF; IF _decision NOT IN ('approved','declined','withdrawn') THEN RAISE EXCEPTION 'Invalid decision'; END IF; IF _decision='withdrawn' THEN IF r.proposed_by<>_actor THEN RAISE EXCEPTION 'Only proposer may withdraw'; END IF; ELSE IF NOT EXISTS(SELECT 1 FROM public.fund_managers WHERE offering_id=r.offering_id AND user_id=_actor) AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_actor AND role::text IN ('admin','super_admin','operations','fund_administration','legal','compliance')) AND NOT public.is_live_fund_reviewer(_actor,r.offering_id) THEN RAISE EXCEPTION 'Exact-fund review authority required'; END IF; END IF; SELECT * INTO l FROM public.side_letters WHERE id=r.side_letter_id AND offering_id=r.offering_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Side letter unavailable'; END IF; UPDATE public.side_letter_change_requests SET status=_decision,decided_by=_actor,decided_at=now(),decision_reason=nullif(btrim(_reason),'') WHERE id=r.id; IF _decision='approved' THEN s:=r.after_snapshot; v:=l.current_version+1; INSERT INTO public.side_letter_versions(side_letter_id,version,snapshot,change_request_id) VALUES(l.id,v,s,r.id); UPDATE public.side_letters SET status=CASE WHEN r.kind='terminate' THEN 'terminated' ELSE 'active' END,investor_label=s->>'investorLabel',mfn_enabled=coalesce((s->>'mfnEnabled')::boolean,false),mfn_scope=CASE WHEN coalesce((s->>'mfnEnabled')::boolean,false) THEN s->>'mfnScope' ELSE NULL END,effective_date=nullif(s->>'effectiveDate','')::date,expiry_date=nullif(s->>'expiryDate','')::date,renewal_note=s->>'renewalNote',document_reference=s->>'documentReference',terms=s->'terms',current_version=v,updated_at=now() WHERE id=l.id; ELSIF r.kind='create' THEN UPDATE public.side_letters SET status='declined',updated_at=now() WHERE id=l.id; END IF; INSERT INTO public.side_letter_events(offering_id,side_letter_id,event,actor_id,detail) VALUES(r.offering_id,l.id,_decision||'_'||r.kind,_actor,jsonb_build_object('change_request_id',r.id,'reason',_reason)); END; $$;
REVOKE ALL ON FUNCTION public.decide_routine_side_letter(uuid,uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.decide_routine_side_letter(uuid,uuid,text,text) TO service_role;